int main(void) {
    int *p = malloc(sizeof *p);
    if (p == NULL) return 1;
    *p = 7;
    int *q = p;
    printf("%d\n", *q);
    free(p);
    p = NULL;
    q = NULL;
    return 0;
}
// Before free: frame p --\
//                        > heap int [7]
